car_plate = #{carPlate}, car_type = #{carType}, space_no = #{spaceNo}, park_type = #{parkType}, entry_time = #{entryTime}, exit_time = #{exitTime}, duration = #{duration}, fee = #{fee}, paid_fee = #{paidFee}, pay_status = #{payStatus}, pay_method = #{payMethod}, pay_time = #{payTime}, gate = #{gate}, operator = #{operator}, remark = #{remark},
WHERE id = #{id}
